// Web -> FS (catálogo) con UPSERT por referencia + SEMBRADO de stock inicial.
// - Si el producto NO existe en FS: lo crea y le pone el stock inicial de la web.
// - Si YA existe: solo actualiza el catálogo; NO toca el stock (a partir de ahí manda FS).
// Pausas entre llamadas para no provocar el 429 de FacturaScripts.
const FS_BASE    = 'http://127.0.0.1/api/3';
const FS_TOKEN   = 'PON_TU_TOKEN_FS';
const WEB_URL    = 'http://127.0.0.1:3000/api/sync/products';
const WEB_SECRET = 'PON_TU_SECRETO_SYNC';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const enc = (o) => Object.entries(o).map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
const H  = { 'X-Auth-Token': FS_TOKEN };
const HF = { 'X-Auth-Token': FS_TOKEN, 'Content-Type': 'application/x-www-form-urlencoded' };

// Almacén por defecto (necesario para crear filas de stock)
let codalmacen = '';
try {
  const alm = await this.helpers.httpRequest({ method: 'GET', url: FS_BASE + '/almacenes?limit=1', headers: H, json: true });
  const la = Array.isArray(alm) ? alm : (alm.data || []);
  if (la.length) codalmacen = la[0].codalmacen;
} catch (e) {}

// Catálogo de la web (solo productos CON SKU)
const web = await this.helpers.httpRequest({ method: 'GET', url: WEB_URL, headers: { 'X-Sync-Secret': WEB_SECRET }, json: true });
const productos = (web.products || []).filter((p) => p.sku && String(p.sku).trim() !== '');

const out = [];
for (const p of productos) {
  const ref = String(p.sku).trim();
  const body = {
    referencia: ref,
    descripcion: p.name,
    precio: Math.round((p.price / 1.21) * 100) / 100,
    codimpuesto: 'IVA21',
    codfamilia: String(p.category_slug || 'varios').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 8),
    sevende: 1, secompra: 0,
  };
  try {
    const found = await this.helpers.httpRequest({ method: 'GET', url: FS_BASE + '/productos?filter[referencia]=' + encodeURIComponent(ref) + '&limit=1', headers: H, json: true });
    const lista = Array.isArray(found) ? found : (found.data || []);
    if (lista.length && lista[0].idproducto) {
      // EXISTE -> actualizar catálogo, NO tocar stock
      await this.helpers.httpRequest({ method: 'PUT', url: FS_BASE + '/productos/' + lista[0].idproducto, headers: HF, body: enc(body) });
      out.push({ json: { referencia: ref, accion: 'actualizado' } });
    } else {
      // NUEVO -> crear producto + sembrar stock inicial
      const creado = await this.helpers.httpRequest({ method: 'POST', url: FS_BASE + '/productos', headers: HF, body: enc(body) });
      const idprod = (creado && (creado.idproducto || (creado.data && creado.data.idproducto))) || null;
      const stockIni = Math.max(0, Math.round(Number(p.stock) || 0));
      let seed = 'sin almacén -> stock 0';
      if (codalmacen) {
        await sleep(1200);
        const st = await this.helpers.httpRequest({ method: 'GET', url: FS_BASE + '/stocks?filter[referencia]=' + encodeURIComponent(ref) + '&limit=1', headers: H, json: true });
        const filas = Array.isArray(st) ? st : (st.data || []);
        if (filas.length && filas[0].idstock) {
          await this.helpers.httpRequest({ method: 'PUT', url: FS_BASE + '/stocks/' + filas[0].idstock, headers: HF, body: enc({ cantidad: stockIni }) });
        } else {
          const sbody = { referencia: ref, codalmacen: codalmacen, cantidad: stockIni };
          if (idprod) sbody.idproducto = idprod;
          await this.helpers.httpRequest({ method: 'POST', url: FS_BASE + '/stocks', headers: HF, body: enc(sbody) });
        }
        seed = 'stock ' + stockIni;
      }
      out.push({ json: { referencia: ref, accion: 'creado', sembrado: seed } });
    }
  } catch (e) {
    out.push({ json: { referencia: ref, accion: 'error', error: String((e && e.message) || e) } });
  }
  await sleep(1300); // pausa anti-429
}
return out.length ? out : [{ json: { info: 'sin productos con SKU' } }];
